import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with tunable ELA features designed for d=2.

    The function is a weighted sum of a skewed quadratic bowl,
    a linear term with interactions, and a simple quadratic. Formula:

    f(x) = 0.  4 * skewed_quadratic(x) + 0.4 * linear_interactions(x) + 0.2 * quadratic_bowl(x)
    """
    def skewed_quadratic(x):
        """A skewed quadratic bowl."""
        return (x[0]**2 + (x[1] + 0.8 * x[0])**2)**0.5 + 0.5 * x[0]**3 - 0.2*x[1]**3

    def linear_interactions(x):
        """A linear function with pairwise interactions."""
        return 2*x[0] + 2*x[1] + 0.8 * x[0] * x[1]

    def quadratic_bowl(x):
        """A simple quadratic bowl function."""
        return x[0]**2 + x[1]**2 + 0.1*np.cos(2*np.pi*x[0])

    return 0.2 * skewed_quadratic(x) + 0.7 * linear_interactions(x) + 0.1 * quadratic_bowl(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with tunable ELA features designed for d=2.

    The function is a weighted sum of a modified skewed quadratic bowl,
    a linear term with stronger interactions, and a reduced simple quadratic. Formula:

    f(x) = 0.6 * skewed_quadratic(x) + 0.3 * linear_interactions(x) + 0.1 * quadratic_bowl(x)
    """
    def skewed_quadratic(x):
        """A more skewed quadratic bowl."""
        return (x[0]**2 + (x[1] + 0.3 * x[0])**2)**0.5 + 0.3 * x[0]**3 + 0.1*np.abs(x[1])

    def linear_interactions(x):
        """A linear function with stronger pairwise interactions."""
        return 0.1*x[0] + 0.1*x[1] + 0.8 * x[0] * x[1]

    def quadratic_bowl(x):
        """A simpler quadratic bowl function."""
        return x[0]**2 + x[1]**2

    return 0.1 * (0.6 * skewed_quadratic(x) + 0.3 * linear_interactions(x) + 0.1 * quadratic_bowl(x))
